package com.spinplayer.app;
import android.content.Context;import java.io.*;import java.util.*;import org.json.*;
/** Only disposable search artwork and orphan download folders are eligible for deletion. */
public final class CacheStorage {
 static Set<String> protectedArt(Context c)throws Exception{Set<String> out=new HashSet<>();JSONArray lib=MusicLibrary.load(c),jobs=OnlineDownloads.load(c);for(int i=0;i<lib.length();i++){out.add(new File(lib.getJSONObject(i).optString("cover").split("\\?",2)[0]).getName());out.add(new File(lib.getJSONObject(i).optString("originalCover").split("\\?",2)[0]).getName());}for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);if(!j.optString("status").equals("done"))out.add(ArtworkCache.file(c,j.optString("cover")).getName());}PlaybackService p=PlaybackService.instance;if(p!=null&&p.track!=null)out.add(new File(p.track.optString("cover").split("\\?",2)[0]).getName());return out;}
 static long bytes(File f){if(java.nio.file.Files.isSymbolicLink(f.toPath()))return 0;if(f.isFile())return f.length();long n=0;File[] list=f.listFiles();if(list!=null)for(File v:list)n+=bytes(v);return n;}
 static List<File> art(Context c)throws Exception{Set<String> keep=protectedArt(c);List<File> out=new ArrayList<>();File[] files=new File(c.getFilesDir(),"art").listFiles();if(files!=null)for(File f:files)if(f.isFile()&&(f.getName().startsWith("online-")||f.getName().startsWith("cover-edit-"))&&f.getName().endsWith(".jpg")&&!keep.contains(f.getName()))out.add(f);return out;}
 static boolean protectedDownload(Context c,File f){return DownloadService.instance!=null||f.lastModified()>System.currentTimeMillis()-86400000L;}
 static void remove(File f){if(java.nio.file.Files.isSymbolicLink(f.toPath()))return;File[] files=f.listFiles();if(files!=null)for(File v:files)remove(v);f.delete();}
 static JSONObject measure(Context c)throws Exception{synchronized(ArtworkCache.class){long images=0,stale=0,active=0,other=0;for(File f:art(c))images+=bytes(f);File[] files=c.getCacheDir().listFiles();if(files!=null)for(File f:files){long size=bytes(f);if(f.getName().startsWith("download-")){if(protectedDownload(c,f))active+=size;else stale+=size;}else other+=size;}return new JSONObject().put("images",images).put("stale",stale).put("active",active).put("other",other).put("limit",100L*1024*1024);}}
 static void clean(Context c,boolean all)throws Exception{synchronized(ArtworkCache.class){List<File> files=art(c);files.sort(Comparator.comparingLong(File::lastModified));long total=0;for(File f:files)total+=f.length();for(File f:files)if(all||total>100L*1024*1024){long size=f.length();if(f.delete())total-=size;}File[] temp=c.getCacheDir().listFiles();if(temp!=null)for(File f:temp)if(f.getName().startsWith("download-")&&!protectedDownload(c,f))remove(f);}}
}
